def main():
    entries = []
    for i, row in enumerate((ROWS + '\n' + EXTRA_ROWS).splitlines(), 1):
        # Rows may mention the boolean pipe operator inside prose.
        category, title, error, explanation, cause, fix = row.split('|', 5)
        entries.append(dict(id=f'ED-{i:03}', title=title, example_error=error, explanation=explanation, likely_cause=cause, fix=fix, tags=[category.lower()]))
    for entry in expanded_entries():
        entries.append({'id': f'ED-{len(entries) + 1:03}', **entry})
    assert len(entries) == 1000, len(entries)
    from collections import Counter
    assert Counter(e['tags'][0] for e in entries) == {'python': 350, 'pandas': 250, 'pip': 175, 'fastapi': 225}
    for field in ('id', 'title', 'example_error'):
        assert len({entry[field] for entry in entries}) == len(entries), field
    Path(__file__).with_name('entries.json').write_text(json.dumps(entries, indent=2), encoding='utf-8')

if __name__ == '__main__':
    main()
